We can first define the gains of Tx and Rx, respectively, as
\begin{subequations} \label{gain_Tx_Rx}
 \begin{align} 
   G_{\mathrm{Tx}} &\!=\! \|{\bf a}_{\mathrm{T}}(m,q)\|_2^2 = \frac{\lambda_c^2}{16\pi^2}\sum_{n_t=1}^{N_t}\frac{1}{r_{n_t}^2} = \frac{\lambda_c^2}{16\pi^2}g_{\mathrm {Tx}}, \label{gain_Tx}\\ 
   G_{\mathrm{Rx}} &\!=\! \|{\bf a}_{\mathrm{R}}(m,q)\|_2^2 = \frac{\lambda_c^2}{16\pi^2}\sum_{n_r=1}^{N_r}\frac{1}{r_{n_r}^2} = \frac{\lambda_c^2}{16\pi^2}g_{\mathrm {Rx}}, \label{gain_Rx}
 \end{align}   
\end{subequations}
where $r_{n_t}=\|{\mathbb I}_{q}-{\mathbb I}_{n_t}\|$ and $r_{n_r}=\|{\mathbb I}_{q}-{\mathbb I}_{n_r}\|$. 
Then, we have 
\begin{flalign} \label{CRB_RCS}
\mathrm{CRB}_{\alpha_{R}}=\mathrm{CRB}_{\alpha_{I}}=\frac{256\sigma_r^2\pi^{4}}{2\mathcal{P}Mg_{\mathrm {Tx}}g_{\mathrm {Rx}}\lambda_c^4}. 
\end{flalign} 
Moreover, we denote $\mathrm{CRB}_{\alpha}=\mathrm{CRB}_{\alpha_{R}}+\mathrm{CRB}_{\alpha_{I}}$ by the CRB for RCS estimation. 





\begin{theorem}
 For a single target with co-located Tx/Rx arrays along with $x$-axis centered at the origin, CRBs for RCS estimation, in terms of far-field and near-field cases, are, respectively, given by
\begin{subequations} \label{CRB_RCS.1}
\begin{flalign} 
&\mathrm{CRB}_{\alpha}^{\mathrm{FF}}  \approx \frac{256\sigma_r^2\pi^{4}(r_{\mathrm{Tx}}^{\mathrm{FF}}r_{\mathrm{Rx}}^{\mathrm{FF}})^2}{\mathcal{P}M{N_t}{N_r}\lambda_c^4}, \label{CRB_RCS.1.1}\\
&\mathrm{CRB}_{\alpha}^{\mathrm{NF}} \! \approx \!\frac{256\sigma_r^2\pi^{4}(r_{\mathrm{Tx}}^{\mathrm{NF}}r_{\mathrm{Rx}}^{\mathrm{NF}})^2}{\mathcal{P}M{N_t}{N_r}(1+\Delta_{\mathrm{Tx}})(1+\Delta_{\mathrm{Rx}})\lambda_c^4}, \label{CRB_RCS.1.2}
\end{flalign} 
\end{subequations}
where  $r_{\mathrm{Tx}}^{\mathrm{FF}}$ and $r_{\mathrm{Rx}}^{\mathrm{FF}}$ denote the range between the far-field target and reference element of Tx and Rx, respectively, and $\Delta_{\mathrm{Tx}}=\frac{(N_t^{2}-1)d_t^2(4\sin^2\theta_{\mathrm{Tx},q} - 1)}{12 r_{\mathrm{Tx}}^2}$ and $\Delta_{\mathrm{Rx}}=\frac{(N_r^{2}-1)d_r^2(4\sin^2\theta_{\mathrm{Rx},q} - 1)}{12 r_{\mathrm{Rx}}^2}$. 
\end{theorem}
\begin{proof}
  See Appendix A. 
\end{proof}

Fig.~\ref{range} and Fig~\ref{angle} display the far-field (first-order Taylor) and near-field (second-order Taylor) approximation error to the true $g_{\mathrm {Tx}}$ or $g_{\mathrm {Rx}}$ in \eqref{gain_Tx_Rx}. Fig.~\ref{range} shows that the error decreases with target range. Meanwhile, the NF approximation is consistently much more accurate, and far-field becomes reliable mainly beyond the Fraunhofer distance. Fig.~\ref{angle} shows that the error depends strongly on the angle and shows symmetric dips. Then, the larger range reduces error and near-field stays better, especially at short or medium ranges.

