\label{app:proof_thm1}
First, for the far-field target, the distances between the target and each element are approximately the same.  Then, we have $g_{\mathrm {Tx}}^{\mathrm{FF}}\approx \frac{N_t}{{r_{\mathrm{Tx}}^{\mathrm{FF}}}^2}$ and $g_{\mathrm {Rx}}^{\mathrm{FF}}\approx \frac{N_r}{{r_{\mathrm{Rx}}^{\mathrm{FF}}}^2}$.
 The approximations in \eqref{CRB_RCS.1.1} hold. 

Let the array be centered at the origin so that the $n_t$-th Tx element,
$n_t=1,\ldots,N_t$, is located at
\begin{equation}
  x_{n_t} = \Bigl(n_t - \frac{N_t+1}{2}\Bigr)d_t , \qquad
  y_{n_t}=0 ,
\end{equation}
and therefore
\begin{equation} \label{gem_sum}
  \sum_{n_t=1}^{N_t} x_{n_t} = 0, \qquad
  \sum_{n_t=1}^{N_t} x_{n_t}^2 = \frac{N_t(N_t^{2}-1)d_t^{2}}{12}.
\end{equation}
Consider a single target located at polar coordinates
$(r_{\mathrm{Tx}},\theta_{\mathrm{Tx},q})$ with respect to the Tx array
centroid, i.e.,
\begin{equation}
  x_q = r_{\mathrm{Tx}}\sin\theta_{\mathrm{Tx},q}, \qquad
  y_q = r_{\mathrm{Tx}}\cos\theta_{\mathrm{Tx},q}.
\end{equation}
The distance between the target and the $n_t$-th Tx element is
\begin{align}
  r_{n_t}
  &= \bigl\|\mathbb{I}_q - \mathbb{I}_{n_t}\bigr\|
   = \sqrt{(x_q - x_{n_t})^{2} + y_q^{2}} \nonumber\\
  &= r_{\mathrm{Tx}}
     \sqrt{1
           - \frac{2x_{n_t}\sin\theta_{\mathrm{Tx},q}}{r_{\mathrm{Tx}}}
           + \frac{x_{n_t}^{2}}{r_{\mathrm{Tx}}^{2}} } .
  \label{eq:rnt_exact}
\end{align}
In the Fresnel region, the array aperture is much smaller than the range,
i.e., $D_t/2 \ll r_{\mathrm{Tx}}$, where
$D_t=(N_t-1)d_t$ is the Tx aperture. Hence, using the second-order
Taylor expansion of $\sqrt{1+\varepsilon}$ for
\[
  \varepsilon
  = - \frac{2x_{n_t}\sin\theta_{\mathrm{Tx},q}}{r_{\mathrm{Tx}}}
    + \frac{x_{n_t}^{2}}{r_{\mathrm{Tx}}^{2}},
\]
we obtain
\begin{align}
  r_{n_t}
  &\approx
  r_{\mathrm{Tx}}
   \left(1 + \frac{\varepsilon}{2} - \frac{\varepsilon^{2}}{8}\right) \nonumber\\
  &\approx
  r_{\mathrm{Tx}}
  - x_{n_t}\sin\theta_{\mathrm{Tx},q}
  + \frac{x_{n_t}^{2}\cos^{2}\theta_{\mathrm{Tx},q}}{2r_{\mathrm{Tx}}}.
  \label{eq:rnt_taylor}
\end{align}
To derive the array gain, we need $1/r_{n_t}^{2}$.  Writing
$r_{n_t}=r_{\mathrm{Tx}}(1+\delta_{n_t})$ with
\begin{equation}
  \delta_{n_t}
  = - \frac{x_{n_t}\sin\theta_{\mathrm{Tx},q}}{r_{\mathrm{Tx}}}
    + \frac{x_{n_t}^{2}\cos^{2}\theta_{\mathrm{Tx},q}}{2r_{\mathrm{Tx}}^{2}},
\end{equation}
and using the second-order expansion $(1+\delta)^{-2}\approx
1-2\delta+3\delta^{2}$ for $|\delta|\ll1$, we get
\begin{align}
 & \frac{1}{r_{n_t}^{2}}
  = \frac{1}{r_{\mathrm{Tx}}^{2}}(1+\delta_{n_t})^{-2} \nonumber\\
  &\approx \frac{1}{r_{\mathrm{Tx}}^{2}}
  \Biggl[
     1
     + \frac{2x_{n_t}\sin\theta_{\mathrm{Tx},q}}{r_{\mathrm{Tx}}}
     + \frac{x_{n_t}^{2}}{r_{\mathrm{Tx}}^{2}}
       \bigl(4\sin^{2}\theta_{\mathrm{Tx},q}-1\bigr)
  \Biggr].
  \label{eq:inv_rnt2_expand}
\end{align}
The total Tx gain is then
\begin{align}
  &g_{\mathrm{Tx}}^{\mathrm{NF}}
  = \sum_{n_t=1}^{N_t} \frac{1}{r_{n_t}^{2}} \label{eq:gTx_sum_def} \\
  &\approx \frac{1}{r_{\mathrm{Tx}}^{2}}
    \sum_{n_t=1}^{N_t}
    \Biggl[
       1
       + \frac{2x_{n_t}\sin\theta_{\mathrm{Tx},q}}{r_{\mathrm{Tx}}}
       + \frac{x_{n_t}^{2}}{r_{\mathrm{Tx}}^{2}}
         \bigl(4\sin^{2}\theta_{\mathrm{Tx},q}-1\bigr)
    \Biggr] \nonumber\\
  &= \frac{N_t}{r_{\mathrm{Tx}}^{2}}
     + \frac{2\sin\theta_{\mathrm{Tx},q}}{r_{\mathrm{Tx}}^{3}}
       \sum_{n_t=1}^{N_t} x_{n_t}
     + \frac{4\sin^{2}\theta_{\mathrm{Tx},q}-1}{r_{\mathrm{Tx}}^{4}}
       \sum_{n_t=1}^{N_t} x_{n_t}^{2}. \label{eq:gTx_sum_expand}
\end{align}
Recalling \eqref{gem_sum}, we finally obtain
\begin{equation} \label{gain_NF_Tx}
  g_{\mathrm{Tx}}^{\mathrm{NF}}
  \approx
  \frac{N_t}{r_{\mathrm{Tx}}^{2}}
  + \frac{N_t(N_t^{2}-1)d_t^{2}}{12r_{\mathrm{Tx}}^{4}}
    \bigl(4\sin^{2}\theta_{\mathrm{Tx},q}-1\bigr).
\end{equation}
It is observed that the near-field channel gain of Tx in \eqref{gain_NF_Tx} is not related to the relative position of each antenna element. Hence, for bistatic case, a similar derivation for the Rx array with $N_r$ elements and spacing
$d_r$ yields
\begin{equation} \label{gain_NF_Rx}
  g_{\mathrm{Rx}}^{\mathrm{NF}}
  \approx
  \frac{N_r}{r_{\mathrm{Rx}}^{2}}
  + \frac{N_r(N_r^{2}-1)d_r^{2}}{12r_{\mathrm{Rx}}^{4}}
    \bigl(4\sin^{2}\theta_{\mathrm{Rx},q}-1\bigr),
\end{equation}
where $r_{\mathrm{Rx}}$ and $\theta_{\mathrm{Rx},q}$ denote the target
range and angle with respect to the Rx array centroid.
Substituting \eqref{gain_NF_Tx} and \eqref{gain_NF_Rx} into \eqref{gain_Tx} and \eqref{gain_Rx}, we get near-field channel gain
\begin{subequations} \label{gain_NF_Tx_Rx}
 \begin{flalign} 
   G_{\mathrm{Tx}}^{\mathrm{NF}} & \!\approx\! \frac{\lambda_c^2N_t}{16\pi^2r_{\mathrm{Tx}}^{2}}(1\!+\!\frac{(N_t^{2}-1)d_t^{2}}{12r_{\mathrm{Tx}}^{2}}(4\sin^{2}\theta_{\mathrm{Tx},q}\!-\!1)), \label{gain_NF_Tx_final}\\ 
   G_{\mathrm{Rx}}^{\mathrm{NF}} & \!\approx\! \frac{\lambda_c^2N_r}{16\pi^2r_{\mathrm{Rx}}^{2}}(1\!+\!\frac{(N_r^{2}-1)d_r^{2}}{12r_{\mathrm{Rx}}^{2}}(4\sin^{2}\theta_{\mathrm{Rx},q}\!-\!1)). \label{gain_NF_Rx_final}
 \end{flalign}   
\end{subequations}
Finally, substituting \eqref{gain_NF_Tx} and \eqref{gain_NF_Rx} into 
\eqref{CRB_RCS}, we can directly obtain \eqref{CRB_RCS.1.2}. This completes the proof.

Analogously, we introduce the partial channel gains associated with the velocity components as
\begin{small}
\begin{subequations} \label{gain_Tx_Rx_vx_vy}
 \begin{align} 
\hspace*{-0.5em}   \acute{G}_{\mathrm{Tx}}(m) &\!=\! \|\acute{\bf a}_{\mathrm{T}}(m,q)\|_2^2 = \frac{ m^2 T_{\mathrm{sym}}^2}
{4}\sum_{n_t=1}^{N_t}\frac{(x_q - x_{n_t})^2}{r_{n_t}^4}, \label{gain_Tx_vx}\\ 
\hspace*{-0.5em}   \acute{G}_{\mathrm{Rx}}(m) &\!=\! \|\acute{\bf a}_{\mathrm{R}}(m,q)\|_2^2 = \frac{ m^2 T_{\mathrm{sym}}^2}
{4}\sum_{n_r=1}^{N_r}\frac{(x_q - x_{n_r})^2}{r_{n_r}^4}, \label{gain_Rx_vx}\\
\hspace*{-0.5em}   \grave{G}_{\mathrm{Tx}}(m) &\!=\! \|\grave{\bf a}_{\mathrm{T}}(m,q)\|_2^2 = \frac{ m^2 T_{\mathrm{sym}}^2}
{4}\sum_{n_t=1}^{N_t}\frac{(y_q - y_{n_t})^2}{r_{n_t}^4}, \label{gain_Tx_vy}\\ 
\hspace*{-0.5em}   \grave{G}_{\mathrm{Rx}}(m) &\!=\! \|\grave{\bf a}_{\mathrm{R}}(m,q)\|_2^2 = \frac{ m^2 T_{\mathrm{sym}}^2}
{4}\sum_{n_r=1}^{N_r}\frac{(y_q - y_{n_r})^2}{r_{n_r}^4}. \label{gain_Rx_vy}
 \end{align}   
\end{subequations}
\end{small}
\noindent\hspace{-1em} Again, for the far-field target, we have $\|\mathbb I_q - \mathbb I_{n_t}\|\approx r_{\mathrm{Tx}}^{\mathrm{FF}}$, $x_q \approx r_{\mathrm{Tx}}^{\mathrm{FF}}\sin\theta_{\mathrm{Tx},q}$. Then, we can far-field partial gain approximation as
\begin{small}
\begin{subequations} \label{FF_gain_Tx_Rx_vx_vy}
 \begin{align} 
   \acute{G}_{\mathrm{Tx}}^{\mathrm{FF}}(m) & \approx \frac{N_t m^2 T_{\mathrm{sym}}^2}{4 {r_{\mathrm{Tx}}^{\mathrm{FF}}}^2}
\left(\sin^2\theta_{\mathrm{Tx},q} \!+\! \frac{(N_t^2-1)d_t^2}{12{r_{\mathrm{Tx}}^{\mathrm{FF}}}^2}
\right), \label{FF_approx_gain_Tx_vx}\\ 
   \acute{G}_{\mathrm{Rx}}^{\mathrm{FF}}(m) & \approx \frac{N_r m^2 T_{\mathrm{sym}}^2}{4 {r_{\mathrm{Rx}}^{\mathrm{FF}}}^2}
\left(\sin^2\theta_{\mathrm{Rx},q} \!+\! \frac{(N_r^2-1)d_r^2}{12{r_{\mathrm{Rx}}^{\mathrm{FF}}}^2}
\right), \label{FF_approx_gain_Rx_vx}\\
   \grave{G}_{\mathrm{Tx}}^{\mathrm{FF}}(m) & \approx \frac{N_t m^2 T_{\mathrm{sym}}^2}{4{r_{\mathrm{Tx}}^{\mathrm{FF}}}^2}
\cos^2\theta_{\mathrm{Tx},q}, \label{FF_approx_gain_Tx_vy}\\ 
   \grave{G}_{\mathrm{Rx}}^{\mathrm{FF}}(m) & \approx \frac{N_r m^2 T_{\mathrm{sym}}^2}{4{r_{\mathrm{Rx}}^{\mathrm{FF}}}^2}
\cos^2\theta_{\mathrm{Rx},q}. \label{FF_approx_gain_Rx_vy}
 \end{align}   
\end{subequations}
\end{small}
The cross term $\Re\!\left\{ 
\acute{\mathbf{a}}_{\mathrm{R}}^{H}(m,q)\mathbf{a}_{\mathrm{R}}(m,q)
\mathbf{a}_{\mathrm{T}}^{H}(m,q)\acute{\mathbf{a}}_{\mathrm{T}}(m,q)
\right\}$ and $\Re\!\left\{ 
\grave{\mathbf{a}}_{\mathrm{R}}^{H}(m,q)\mathbf{a}_{\mathrm{R}}(m,q)
\mathbf{a}_{\mathrm{T}}^{H}(m,q)\grave{\mathbf{a}}_{\mathrm{T}}(m,q)
\right\}$ can be calculated by
\begin{small}
\begin{subequations}
\begin{align}
&\hspace*{-0.5em}\acute{G}_{\mathrm{cr.}}(m)  = 
\frac{\lambda_k^2 m^2 T_{\mathrm{sym}}^2}{64\pi^2}
\sum_{n_r=1}^{N_r} \sum_{n_t=1}^{N_t}
\frac{(x_q - x_{n_r})(x_q - x_{n_t})}{r_{n_r}^3 r_{n_t}^3},\\
& \hspace*{-0.5em}\grave{G}_{\mathrm{cr.}}(m) = 
\frac{\lambda_k^2 m^2 T_{\mathrm{sym}}^2}{64\pi^2}
\sum_{n_r=1}^{N_r} \sum_{n_t=1}^{N_t}
\frac{y_q^2}{r_{n_r}^3 r_{n_t}^3}.
\end{align}
\end{subequations}
\end{small}
Its far-field approximation can be directly given by 
\begin{subequations} \label{cross_approx_FF}
\begin{align} 
&\acute{G}_{\mathrm{cr.}}^{\mathrm{FF}}(m) \approx \frac{N_t N_r \lambda_k^{2} m^{2} T_{\mathrm{sym}}^{2}}
{64 \pi^{2} r_{\mathrm{Tx}}^{2} r_{\mathrm{Rx}}^{2}}
\sin\theta_{\mathrm{Tx},q}\sin\theta_{\mathrm{Rx},q},\\
& \grave{G}_{\mathrm{cr.}}^{\mathrm{FF}}(m) \approx \frac{N_t N_r \lambda_k^{2} m^{2} T_{\mathrm{sym}}^{2}}
{64 \pi^{2} r_{\mathrm{Tx}}^{2} r_{\mathrm{Rx}}^{2}}
\cos\theta_{\mathrm{Tx},q}\cos\theta_{\mathrm{Rx},q}.
\end{align}
\end{subequations}
Substituting \eqref{FF_gain_Tx_Rx_vx_vy} and \eqref{cross_approx_FF} into \eqref{CRB_vel.q1_single} and \eqref{CRB_vel.q2_single}, we can directly get 
\eqref{CRB_vel_FF_final}.

For the near-field target, we have 
\begin{small}
\begin{subequations} \label{NF_gain_Tx_Rx_vx_vy}
 \begin{align} 
   \acute{G}_{\mathrm{Tx}}^{\mathrm{NF}}(m) & \approx 
\frac{N_t m^{2} T_{\mathrm{sym}}^{2}}{4{r_{\mathrm{Tx}}^{\mathrm{NF}}}^{2}}
B_{\mathrm{Tx}}^{(x)}, \label{NF_approx_gain_Tx_vx}\\ 
   \acute{G}_{\mathrm{Rx}}^{\mathrm{NF}}(m) & \approx \frac{N_r m^{2} T_{\mathrm{sym}}^{2}}{4{r_{\mathrm{Rx}}^{\mathrm{NF}}}^{2}}
B_{\mathrm{Rx}}^{(x)}, \label{NF_approx_gain_Rx_vx}\\
   \grave{G}_{\mathrm{Tx}}^{\mathrm{NF}}(m) & \approx \frac{N_t m^{2} T_{\mathrm{sym}}^{2}}{4{r_{\mathrm{Tx}}^{\mathrm{NF}}}^{2}}
B_{\mathrm{Tx}}^{(Y)}, \label{NF_approx_gain_Tx_vy}\\ 
   \grave{G}_{\mathrm{Rx}}^{\mathrm{NF}}(m) & \approx \frac{N_r m^{2} T_{\mathrm{sym}}^{2}}{4{r_{\mathrm{Rx}}^{\mathrm{NF}}}^{2}}
B_{\mathrm{Rx}}^{(y)}. \label{NF_approx_gain_Rx_vy}
 \end{align}   
\end{subequations}
\end{small}
\noindent\hspace{-0.5em}Similarly, the cross term approximation of near-field target can be given by 
\begin{small}
\begin{subequations} \label{cross_approx_NF}
\begin{align} 
&\acute{G}_{\mathrm{cr.}}^{\mathrm{NF}}(m) \!\approx\! \frac{N_t N_r \lambda_k^{2} m^{2} T_{\mathrm{sym}}^{2}}
{64 \pi^{2} r_{\mathrm{Tx}}^{2} r_{\mathrm{Rx}}^{2}}
\sin\theta_{\mathrm{Tx},q}\sin\theta_{\mathrm{Rx},q}\left(1\!+\!\Delta_{x,\mathrm{Tx}}^{\mathrm{NF}}\!+\!\Delta_{x,\mathrm{Rx}}^{\mathrm{NF}}
\right)
,\\
& \grave{G}_{\mathrm{cr.}}^{\mathrm{NF}}(m) \!\approx\! \frac{N_t N_r \lambda_k^{2} m^{2} T_{\mathrm{sym}}^{2}}
{64 \pi^{2} r_{\mathrm{Tx}}^{2} r_{\mathrm{Rx}}^{2}}
\cos\theta_{\mathrm{Tx},q}\cos\theta_{\mathrm{Rx},q}\left(1\!+\!\Delta_{y,\mathrm{Tx}}^{\mathrm{NF}}\!+\!\Delta_{y,\mathrm{Rx}}^{\mathrm{NF}}\right).
\end{align}
\end{subequations}
\end{small}
\noindent\hspace{-0.5em}Substituting \eqref{gain_NF_Tx_Rx}, \eqref{NF_gain_Tx_Rx_vx_vy} and \eqref{cross_approx_NF} into \eqref{CRB_loc.q1_single} and \eqref{CRB_loc.q2_single}, we can directly obtain \eqref{CRB_vel_NF_final}. This completes the proof.




